windows.script:
; Sort() is the branch, kept on its own so it opens as a flowchart of
; its own on the Steps tab: one test, three ways out. Every line in it
; is a shape the step editor itself writes.
Sort(address, body, took) {
    global g, results, checked, good, slow, broken
    if (body = "") {
        broken += 1
        state := "Down"
    } else if (took > 1200) {
        slow += 1
        state := "Slow"
    } else {
        good += 1
        state := "Up"
    }
    checked += 1
    results.Component.AddRow({Key: address, site: address, state: state, took: took, size: StrLen(body)})
    AxBindSync()
}

events.code:
only := ""
for row in results.Component.Rows {
    if (row.state = "Down") {
        only .= (only = "" ? "" : "`n") row.site
    }
}
if (only = "") {
    MsgBox("Nothing was down.")
    return
}
sites := only
AxBindSync()
goBtn_Click(goBtn, 0, 0)
